mapper.select:
SELECT * FROM material_item WHERE shelf_status = 'PUBLISHED' AND deleted = 0
AND category_id = #{categoryId}
ORDER BY last_inbound_at DESC, id DESC

SELECT * FROM material_item WHERE deleted = 0
AND category_id = #{categoryId}
ORDER BY id DESC

SELECT i.* FROM material_item i WHERE i.deleted = 0 AND i.category_id = #{categoryId}
AND i.id IN ( SELECT DISTINCT l.item_id FROM material_request_line l JOIN material_request r ON l.request_id = r.id WHERE r.deleted = 0 AND r.applicant_group = #{applicantGroup} UNION SELECT DISTINCT m.item_id FROM material_stock_movement m LEFT JOIN material_request r2 ON m.request_id = r2.id LEFT JOIN aro_personnel p ON m.applicant_user_id = p.user_id WHERE r2.applicant_group = #{applicantGroup} OR p.project_group_name = #{applicantGroup} )
ORDER BY i.id DESC

mapper.update:
UPDATE material_item
SET category_id = #{categoryId}, name = #{name}, subtitle = #{subtitle}, cover_url = #{coverUrl},
    shelf_status = #{shelfStatus}, stock_mode = #{stockMode}, show_stock_qty = #{showStockQty},
    workflow_type = #{workflowType}, reviewer_ids = #{reviewerIds}, second_reviewer_ids = #{secondReviewerIds}
WHERE id = #{id}
